var staticData = $getWorkflowStaticData('global');
if (!staticData.prepped) staticData.prepped = {};

var now = new Date();
var cutoff = now.getTime() - 24 * 60 * 60 * 1000;
Object.keys(staticData.prepped).forEach(function(key) {
  if (new Date(staticData.prepped[key]).getTime() < cutoff) delete staticData.prepped[key];
});

var events = $input.all().map(function(item) { return item.json; });
var unprepped = events.filter(function(e) {
  if (!e.start || !e.start.dateTime) return false;
  if (e.status === 'cancelled') return false;
  var attendees = e.attendees || [];
  var others = attendees.filter(function(a) { return a.email !== 'nelson.torres@adquadrant.com' && !a.self; });
  if (attendees.length > 0 && others.length === 0) return false;
  var key = 'prep_' + e.id;
  if (staticData.prepped[key]) return false;
  return true;
});

if (unprepped.length === 0) {
  return [{ json: { has_meetings: false, meeting_count: 0 } }];
}

var meetings = unprepped.map(function(e) {
  var attendees = (e.attendees || []).filter(function(a) { return a.email !== 'nelson.torres@adquadrant.com' && !a.self; });
  var start = new Date(e.start.dateTime);
  var end = new Date(e.end.dateTime);
  staticData.prepped['prep_' + e.id] = now.toISOString();
  return {
    id: e.id,
    title: e.summary || 'Untitled Meeting',
    start: start.toLocaleTimeString('en-US', { hour: 'numeric', minute: '2-digit' }),
    end: end.toLocaleTimeString('en-US', { hour: 'numeric', minute: '2-digit' }),
    duration: Math.round((end - start) / (1000 * 60)),
    attendees: attendees.map(function(a) { return { name: a.displayName || a.email.split('@')[0], email: a.email }; }),
    joinLink: e.hangoutLink || (e.conferenceData && e.conferenceData.entryPoints && e.conferenceData.entryPoints[0] ? e.conferenceData.entryPoints[0].uri : ''),
    description: e.description || ''
  };
});

var searchTerms = meetings.map(function(m) { return m.title; });
var attendeeNames = [];
meetings.forEach(function(m) { m.attendees.forEach(function(a) { if (attendeeNames.indexOf(a.name) === -1) attendeeNames.push(a.name); }); });
var searchQuery = searchTerms.concat(attendeeNames.slice(0, 3)).join(' OR ');

return [{ json: {
  has_meetings: true,
  meeting_count: meetings.length,
  meetings: meetings,
  search_query: searchQuery
}}];

