const slackResults = $input.all().map(item => item.json);

const slackContext = slackResults.filter(r => r.text).slice(0, 8).map(r => {
  return "- [" + (r.username || "unknown") + " in #" + ((r.channel && r.channel.name) || "dm") + "]: " + (r.text || "").substring(0, 200);
}).join("\n");

