      stateContext || "No state context available.",
      "",
      "Format the output EXACTLY as:",
      "\u2705 *Shipped*",
      "\u2022 [item] \u2014 [brief note]",
      "",
      "\ud83d\udd04 *In Progress*",
      "\u2022 [item] \u2014 [status/next step]",
      "",
      "\ud83d\udea7 *Blockers*",
      "\u2022 [item] \u2014 [what's blocking]",
      "",
      'If no items in a category, write "None". Keep each bullet to one line. Max 12 bullets total.'
    ].join("\n");
  }

