      "Prep brief for a client call.",
      "Client: " + (m.clientName || "Unknown"),
      "Meeting: " + m.title + " at " + m.start + " (" + m.duration + "min)",
      "Attendees: " + att,
      desc ? "Agenda: " + desc : "",
      "",
      "Recent Slack context:",
      slackContext || "No recent Slack context found.",
      "",
      "Format:",
      "*Context* \u2014 1-2 sentences on where things stand with this client",
      "*Talking Points* \u2014 3-5 bullets",
      "*Questions to Ask* \u2014 2-3 bullets",
      "*Open Items* \u2014 anything Nelson needs to follow up on"
    ].join("\n");
  }

  if (m.meetingType === "ONE_ON_ONE") {
    return [
      "1:1 prep for Nelson.",
      "With: " + (m.personName || att),
      desc ? "Agenda: " + desc : "",
      "",
      "Recent Slack:",
      slackContext || "No recent Slack context found.",
      "",
      "Format:",
      "*Context* \u2014 relationship/recent work",
      "*Topics to Cover* \u2014 3-4 bullets",
      "*Bring Up* \u2014 anything outstanding"
    ].join("\n");
  }

