    return [
      "Kickoff prep.",
      "Meeting: " + m.title + " at " + m.start,
      "Attendees: " + att,
      desc ? "Background: " + desc : "",
      "",
      "Format:",
      "*Goals* \u2014 what should be established in this kickoff",
      "*Key Questions* \u2014 4-5 questions to get answered",
      "*Attendees & Roles* \u2014 who's who"
    ].join("\n");
  }

  if (m.meetingType === "EXTERNAL_CALL") {
    return [
      "External call prep.",
      "Meeting: " + m.title + " at " + m.start,
      "External attendees: " + att,
      desc ? "Context: " + desc : "",
      "",
      "Format:",
      "*Who They Are* \u2014 1-2 sentences",
      "*What to Watch For* \u2014 2-3 bullets",
      "*Questions to Ask* \u2014 3 questions"
    ].join("\n");
  }

