    return [
      "Internal sync prep.",
      "Meeting: " + m.title + " at " + m.start,
      "With: " + att,
      desc ? "Agenda: " + desc : "",
      "",
      "Recent Slack:",
      slackContext || "No recent Slack context found.",
      "",
      "Format:",
