const AQ_DOMAIN = "adquadrant.com";

function classifyMeeting(m) {
  const title = (m.title || "").toLowerCase();
  const desc = (m.description || "").toLowerCase();
  const text = title + " " + desc;
  const attendees = m.attendees || [];
  const hasExternal = attendees.some(a => a.email && !a.email.endsWith("@" + AQ_DOMAIN));

  if (/huddle|standup|stand-up|daily standup|daily scrum/.test(title)) {
    return { meetingType: "DAILY_STANDUP", confidence: "high" };
  }
  if (/1:1|1-on-1|one on one|1 on 1/.test(title)) {
    const person = attendees.find(a => !a.self);
    return { meetingType: "ONE_ON_ONE", confidence: "high", personName: person ? person.name : null };
  }
  for (const client of CLIENTS) {
    if (text.includes(client)) {
      const clientName = client.split(" ").map(w => w[0].toUpperCase() + w.slice(1)).join(" ");
      return { meetingType: "CLIENT_CALL", confidence: "high", clientName };
    }
  }
  if (/kickoff|kick off|kick-off/.test(title)) {
    return { meetingType: "KICKOFF", confidence: "high" };
  }
  if (hasExternal) {
    return { meetingType: "EXTERNAL_CALL", confidence: "medium" };
  }
  if (attendees.length > 0) {
    return { meetingType: "INTERNAL_SYNC", confidence: "medium" };
  }
  return { meetingType: "UNKNOWN", confidence: "low" };
}

